      }
    }
    __syncthreads();

    float sum = tot_s[row_in_block];
    float sq = tot_ss[row_in_block];
    float mean = sum * (1.0f / 768.0f);
    float var = sq * (1.0f / 768.0f) - mean * mean;
    float inv = rsqrtf(var + 1e-5f);

    const float4* w4 = reinterpret_cast<const float4*>(w);
